    const h = cell / (2 + 1 / PHI)
    const stroke = scaleColor(i, { seedHue: A432_HUE, dark: true, L: 7 / 8, C: SVG_CHROMA })
    const up = el === 'fire' || el === 'air'
    const tip = up ? y - h : y + h
    const baseY = up ? y + h / 2 : y - h / 2
