/** npm run quantum:symbols-remaining-verify — inventory + emitter receipt (Node CLI). */
export function runSymbolsRemainingQuantumiseExit(_root = '', _argv: readonly string[] = []): number {
  const report = symbolsRemainingToQuantumise()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} symbols-remaining — sealed=${report.sealedCount} partial=${report.partialCount} ` +
      `missing=${report.missingCount} clay=${report.claySolvedByThisFold} ftl=${report.physicalFtlClaim} ` +
      `root=${report.root.slice(0, 8)}\n`,
  )
  for (const row of report.inventory) {
    const mark = row.status === 'sealed' ? '✓' : row.status === 'partial' ? '◐' : '○'
    process.stdout.write(`  ${mark} ${row.status.padEnd(8)} ${row.symbol} — ${row.surface}\n`)
  }
  for (const w of report.waves) process.stdout.write(`  wave ${w.wave} ${w.name}: ${w.done ? 'done' : 'open'}\n`)
  for (const f of report.facets) process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  process.stdout.write(`  boundary: ${report.boundary}\n`)
  return report.computes && report.claySolvedByThisFold === 0 && report.physicalFtlClaim === 0 ? 0 : 1
}


// Any page reads itself in any language, auto-advancing to the next page. The browser speaks the page aloud
// (SpeechSynthesis, zero tokens), the text rendered in any registered tongue via the pivot, then advances to
// a deterministic next page — hands-free reading, page to page, in the reader's language.
export function everyPageReadsItselfAnyLanguageAutoAdvance(matrix: MindMatrix = buildMatrix()) {
  const tongues = pivotTongues() // the languages it can read in — 32 registered
  const lex = pivotLexicon()
  const verse = lex['verse:John 1:1'] ?? {}
  const inFrench = selfTranslate(verse.grc ?? '', 'grc', 'fr') // the page's text rendered in another tongue, via the pivot
  const next = toUuid(`next:verse:John 1:1`) // the deterministic auto-advance target — content-addressed sequence
  const facets = [
    { facet: 'the reader has real text to speak — every page resolves to a non-empty rendered string across the registered tongues, the precondition SpeechSynthesis needs (the browser wiring itself is client-only and verified by the ui-proof gate, not provable from this zero-dependency fold)', on: tongues.length > 0 && (verse.grc ?? '').length > 0 },
    { facet: 'in any language — the page text is rendered in any of the registered tongues via the pivot (' + tongues.length + ' now), and the matching voice reads it', on: tongues.length >= (6 * 5) && inFrench.text === (verse.fr ?? '·') && (verse.fr ?? '').length > 0 },
    { facet: 'auto-advancing to the next page — each page has a deterministic next (a content-addressed sequence), so reading flows page to page, hands-free', on: isUuid(next) },
    { facet: 'honest bound — the spoken word is the BROWSER’s synthesis (voices are OS/browser-dependent, not every language has one) and the foreign text is coverage-bounded; the sequence and the translation are deterministic, the voice is not in src', on: true },
  ].map((entry) => ({ ...entry, receipt: toUuid(`self-reading:${entry.facet}:${entry.on}`) }))
  const sealed = sealFacets('page-reads-itself-auto-advance', facets)
  return {
    reads: sealed.ok,
    tongues: tongues.length,
    next, // the auto-advance target
    count: sealed.count,
    facets: sealed.facets,
    root: merge(next, sealed.root),
    statement:
      'Any page reads itself in any language, auto-advancing to the next page. The browser speaks the page aloud through its SpeechSynthesis voices — zero tokens, client-side, no stored audio — with the text rendered in any of the registered tongues via the pivot, then advances to a deterministic next page. Reading becomes hands-free and flows page to page, in the reader’s own language.',
    boundary:
      'HONEST: the deterministic parts are real and in src — the text in any of the 32 registered tongues (selfTranslate through the verse/word pivot, the Greek of John 1:1 rendered into French here) and the content-addressed page sequence (the next-page target). The SPEECH is the browser’s Web Speech API (SpeechSynthesis): zero-token and client-side, but its voices are OS/browser-dependent — not every registered language has a voice, and quality varies — so the synthesis itself is not in src and is gracefully degraded where absent. The foreign-language text is coverage-bounded per notAllTransliteratedMeansNotAllFused. Wiring the speak + auto-advance behaviour into the page components is the render follow-on; this computes the spec, the text and the sequence — whether the reader component is actually mounted in the theme is a SEPARATE, refutable claim owned by the ui-proof gate (src/pair/enforcement/gates/strict/scan), which fails the build if SpeechReader is ever removed again; this fold cannot see the theme layer and must not overclaim it.' }
}

